import React from 'react';
import { ListGroup, Navbar } from 'react-bootstrap';
import { Gear,
  // Lightbulb,
  Play, Stop } from 'react-bootstrap-icons';
import { useStoreActions, useStoreState } from '../../model';
import {
  NavIcon,
  NavItem,
  NavText,
  NavExtra,
  SideNav,
  // Toggle,
} from '../side-nav/side-nav';
import {
  SelectClarityThreshold,
  SelectNoteSpan,
  SelectTimeSpan,
  SelectDetector,
  SelectDisplayType,
  SelectWindowSize,
} from './options';

import './app-frame.css';

export function AppFrame({ children }: { children: React.ReactNode }) {
  const [menuExpanded, setMenuExpanded] = React.useState(false);
  const [running, setRunning] = React.useState(false);
  const clarityThreshold = useStoreState((state) => state.clarityThreshold);
  const noteSpan = useStoreState((state) => state.noteSpan);
  const timeSpan = useStoreState((state) => state.timeSpan);

  const { initializeStream, stopStream, setEnabled } = useStoreActions(
    (actions) => actions
  );

  React.useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      if (e.code === 'Space') {
        e.preventDefault();
        setRunning(!running);
      }
      if (e.code === 'Escape') {
        setMenuExpanded(false);
      }
      if (e.code === 'KeyS') {
        setMenuExpanded(!menuExpanded);
      }
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [running, menuExpanded]);

  React.useEffect(() => {
    if (running) {
      (async () => {
        await initializeStream();
        setEnabled(true);
        console.log('Stream Initialized');
      })();
    } else {
      (async () => {
        setEnabled(false);
        await stopStream();
        console.log('Stream Stopped');
      })();
    }

    return stopStream;
  }, [initializeStream, running, setEnabled, stopStream]);

  return (
    <React.Fragment>
      <Navbar variant="dark">
        <Navbar.Brand>Pitch Detector</Navbar.Brand>
      </Navbar>
      <div className="main-container">
        <SideNav expanded={menuExpanded} onToggle={setMenuExpanded}>
          {/* <Toggle /> */}
          <SideNav.Nav>
            <NavItem
              className={running ? 'active' : ''}
              onClick={() => {
                setRunning(!running);
              }}
            >
              {running ? (
                <React.Fragment>
                  <NavIcon>
                    <Stop size="20" />
                  </NavIcon>
                  <NavText>Stop</NavText>
                </React.Fragment>
              ) : (
                <React.Fragment>
                  <NavIcon>
                    <Play size="20" />
                  </NavIcon>
                  <NavText>Start</NavText>
                </React.Fragment>
              )}
            </NavItem>
            <NavItem
              onClick={() => {
                setMenuExpanded(!menuExpanded);
              }}
            >
              <NavIcon>
                <Gear size="20" />
              </NavIcon>
              <NavText>Settings</NavText>
            </NavItem>
            <NavExtra>
              <ListGroup variant="flush" color="primary">
                <ListGroup.Item>
                  <div className="setting">
                    <span className="setting-desc">Window Size</span>
                    <SelectWindowSize />
                  </div>
                </ListGroup.Item>
                <ListGroup.Item>
                  <div className="setting">
                    <span className="setting-desc">Detector</span>
                    <SelectDetector />
                  </div>
                </ListGroup.Item>
                <ListGroup.Item>
                  <div className="setting">
                    <span className="setting-desc">
                      Clarity Threshold ({clarityThreshold})
                    </span>
                    <SelectClarityThreshold />
                  </div>
                </ListGroup.Item>
                <ListGroup.Item>
                  <div className="setting">
                    <span className="setting-desc">
                      Note Span ({noteSpan})
                    </span>
                    <SelectNoteSpan />
                  </div>
                </ListGroup.Item>
                <ListGroup.Item>
                  <div className="setting">
                    <span className="setting-desc">
                      Time Span ({timeSpan || 1})
                    </span>
                    <SelectTimeSpan />
                  </div>
                </ListGroup.Item>
                <ListGroup.Item>
                  <div className="setting">
                    <span className="setting-desc">Display Type</span>
                    <SelectDisplayType />
                  </div>
                </ListGroup.Item>
              </ListGroup>
            </NavExtra>
            {/* <NavItem
              className={'mt-auto' + (running ? '' : ' active')}
              onClick={() => {
                // The about screen automatically shows when the app is not running,
                // so this is a shortcut to show the about screen
                setRunning(false);
              }}
            >
              <NavIcon>
                <Lightbulb size="20" />
              </NavIcon>
              <NavText>About</NavText>
            </NavItem> */}
          </SideNav.Nav>
        </SideNav>
        <main
          role="main"
          className="main"
          onClick={() => {
            setMenuExpanded(false);
          }}
        >
          {children}
        </main>
      </div>
    </React.Fragment>
  );
}
