import { scaleLinear } from 'd3-scale';
import { NOTE_STRINGS } from '../constants';
import { noteFromPitch, colorFromNote, centsOffFromPitch } from '../utils';
class PitchDisplay {
    constructor(container) {
        this.frequencies = [];
        this.delay = 50; // ms before a note is shown
        this.background = '#efefef';
        this.highlight = '#888888';
        this.noteSpan = 13;
        this.timeSpan = 5000;
        this.noiseReduction = true;
        this.container = container;
        this.container.style.position = "relative";
        const canvasStyle = "position: absolute; width: 100%; height: 100%;";
        this.bgCanvas = document.createElement("canvas");
        this.bgCanvas.setAttribute("style", canvasStyle);
        this.bgCanvas.oncontextmenu = () => false;
        this.bgContext = this.bgCanvas.getContext('2d');
        this.noteCanvas = document.createElement("canvas");
        this.noteCanvas.setAttribute("style", canvasStyle);
        this.noteCanvas.oncontextmenu = () => false;
        this.noteContext = this.noteCanvas.getContext('2d');
        this.container.appendChild(this.bgCanvas);
        this.container.appendChild(this.noteCanvas);
        this.noteOffset = 60 - this.noteSpan / 2; // 60 = middle C
        this.resize();
    }
    resize() {
        let w = this.container.clientWidth;
        let h = this.container.clientHeight;
        this.bgCanvas.width = w;
        this.bgCanvas.height = h;
        this.noteCanvas.width = w;
        this.noteCanvas.height = h;
        this.scaleX = scaleLinear()
            .domain([-this.timeSpan, this.timeSpan / 5])
            .range([0, w]);
        this.scaleY = scaleLinear()
            .domain([0, this.noteSpan])
            .range([h, 0]);
        this.render();
    }
    pushFrequency(frequency) {
        this.frequencies.push(frequency);
    }
    cleanupFrequencies() {
        if (this.noiseReduction) {
            // significant humble attempt at reducing noise spikes...
            const timeCutoff = 50;
            const keep = new Array(this.frequencies.length).fill(true);
            for (let i = 0; i < this.frequencies.length - 4; ++i) {
                let n1 = noteFromPitch(this.frequencies[i].frequency);
                n1 = n1 + centsOffFromPitch(this.frequencies[i].frequency, n1) / 100;
                let t1 = this.frequencies[i].time;
                let n2 = noteFromPitch(this.frequencies[i + 1].frequency);
                n2 = n2 + centsOffFromPitch(this.frequencies[i + 1].frequency, n2) / 100;
                let t2 = this.frequencies[i + 1].time;
                let n3 = noteFromPitch(this.frequencies[i + 2].frequency);
                n3 = n3 + centsOffFromPitch(this.frequencies[i + 2].frequency, n3) / 100;
                let t3 = this.frequencies[i + 2].time;
                let n4 = noteFromPitch(this.frequencies[i + 3].frequency);
                n4 = n4 + centsOffFromPitch(this.frequencies[i + 3].frequency, n4) / 100;
                let t4 = this.frequencies[i + 3].time;
                let n5 = noteFromPitch(this.frequencies[i + 4].frequency);
                n5 = n5 + centsOffFromPitch(this.frequencies[i + 4].frequency, n5) / 100;
                let t5 = this.frequencies[i + 4].time;
                if (Math.abs(n1 - n2) >= 3
                    && Math.abs(n4 - n5) >= 3
                    && Math.abs(n2 - n3) <= 1
                    && Math.abs(n3 - n4) <= 1
                    && t2 - t1 < timeCutoff
                    && t3 - t2 < timeCutoff
                    && t4 - t3 < timeCutoff
                    && t5 - t4 < timeCutoff) {
                    keep[i + 1] = false;
                    keep[i + 2] = false;
                    keep[i + 3] = false;
                }
                if (Math.abs(n1 - n2) >= 3
                    && Math.abs(n3 - n4) >= 3
                    && Math.abs(n2 - n3) <= 1
                    && t2 - t1 < timeCutoff
                    && t3 - t2 < timeCutoff
                    && t4 - t3 < timeCutoff) {
                    keep[i + 1] = false;
                    keep[i + 2] = false;
                }
                if (Math.abs(n1 - n2) >= 3
                    && Math.abs(n2 - n3) >= 3
                    && t2 - t1 < timeCutoff
                    && t3 - t2 < timeCutoff) {
                    keep[i + 1] = false;
                }
            }
            this.frequencies = this.frequencies.filter((_, i) => keep[i]);
        }
        // Throw away the frequencies that are out of the current display window
        this.frequencies = this.frequencies.filter((val) => this.now - val.time < this.timeSpan);
    }
    setNow(now) {
        this.now = now;
    }
    render(full = true) {
        this.cleanupFrequencies();
        this.calculateOffset();
        if (full) {
            this.drawBackground();
        }
        this.drawNotes();
    }
    setBackgroundColor(color) {
        this.background = color;
        this.drawBackground();
    }
    setHighlightColor(color) {
        this.highlight = color;
        this.drawBackground();
    }
    setNoteSpan(noteSpan) {
        this.noteSpan = noteSpan;
        this.noteOffset = 60 - this.noteSpan / 2;
        this.resize();
    }
    setTimeSpan(timeSpan) {
        this.timeSpan = timeSpan;
        this.resize();
    }
    calculateOffset() {
        if (this.frequencies.length) {
            const margin = this.noteSpan / 16;
            for (let f of this.frequencies) {
                if (this.now - f.time < this.delay)
                    continue;
                let note = noteFromPitch(f.frequency);
                note = note + centsOffFromPitch(f.frequency, note) / 100;
                if (note - margin < this.noteOffset)
                    this.noteOffset = note - margin;
                else if (note - this.noteSpan + margin > this.noteOffset)
                    this.noteOffset = note - this.noteSpan + margin;
            }
        }
    }
    toggleNoiseReduction() {
        this.noiseReduction = !this.noiseReduction;
        console.log('noiseReduction', this.noiseReduction);
    }
    drawBackground() {
        let w = this.bgCanvas.width;
        let h = this.bgCanvas.height;
        this.bgContext.fillStyle = this.background;
        this.bgContext.clearRect(0, 0, w, h);
        this.bgContext.fillRect(0, 0, w, h);
        let i = Math.ceil(this.noteOffset);
        for (let _ = 0; _ < this.noteSpan; ++_) {
            let y = this.scaleY(i - this.noteOffset);
            this.bgContext.fillStyle = this.highlight + '55';
            this.bgContext.fillRect(0, y, w, 1);
            this.bgContext.fillStyle = this.highlight;
            this.bgContext.font = '12px Sans';
            const label = NOTE_STRINGS[(i % 12 + 12) % 12] + (Math.floor(i / 12) - 1);
            this.bgContext.fillText(label, this.scaleX(0) + 20, y - 2);
            this.bgContext.fillText(label, 20, y - 2);
            ++i;
        }
        this.bgContext.fillStyle = this.highlight + '55';
        this.bgContext.fillRect(this.scaleX(0), 0, 1, h);
    }
    drawNotes() {
        let w = this.noteCanvas.width;
        let h = this.noteCanvas.height;
        this.noteContext.clearRect(0, 0, w, h);
        this.noteContext.beginPath();
        this.noteContext.strokeStyle = 'rgba(0, 0, 0, 0.1)';
        // Calculate notes and colors from frequencies
        const notes = [];
        for (let frequency of this.frequencies) {
            if (this.now - frequency.time < this.delay)
                continue;
            let t = frequency.time;
            let f = frequency.frequency;
            let c = frequency.clarity;
            let note = noteFromPitch(f);
            note = note + centsOffFromPitch(f, note) / 100;
            let x = this.scaleX(t - (this.now - this.delay));
            let y = this.scaleY(note - this.noteOffset);
            let color = colorFromNote(note);
            notes.push({
                time: t,
                x,
                y,
                clarity: c,
                color
            });
        }
        // Draw lines
        const timeCutoff = 50;
        this.noteContext.beginPath();
        for (let i = 1; i < notes.length; ++i) {
            const { x, y, time } = notes[i];
            const prevTime = notes[i - 1].time;
            if (time - prevTime > timeCutoff) {
                this.noteContext.stroke();
                this.noteContext.beginPath();
                this.noteContext.moveTo(x, y);
            }
            else {
                this.noteContext.lineTo(x, y);
            }
        }
        this.noteContext.stroke();
        // Draw circles
        for (let note of notes) {
            const { x, y, clarity, color } = note;
            this.noteContext.fillStyle = `rgba(${color[0]}, ${color[1]}, ${color[2]}, ${clarity * 0.5})`;
            this.noteContext.beginPath();
            // this.noteContext.arc(x, y, 3, 0, Math.PI * 2);
            this.noteContext.arc(x, y, clarity == 0.5 ? 15 : 3, 0, Math.PI * 2);
            this.noteContext.fill();
            // console.log(clarity)
        }
    }
}
export { PitchDisplay };
