import React, { Component } from 'react';

import { PitchDisplay } from 'pitch-display';

import { BACKGROUND } from '../../constants/colors';

export interface PitchProps {
  freq: number | null;
  clarity?: number | null;
  noteSpan?: number;
  timeSpan?: number;
}

class PitchComponent extends Component<PitchProps> {
  displayElement = React.createRef<HTMLDivElement>();
  pitchDisplay?: PitchDisplay;
  lastRender: number = 0;
  continuousUpdate: boolean = true;
  paused: boolean = false;

  componentDidMount() {
    this.pitchDisplay = new PitchDisplay(this.displayElement.current!);
    this.pitchDisplay.setBackgroundColor(BACKGROUND);
    this.pitchDisplay.setNoteSpan(this.props.noteSpan ?? 0);
    this.pitchDisplay.setTimeSpan(this.props.timeSpan || 1);

    // We want to ensure `pitchDisplay` updates at regular
    // time intervals even if the note has not changed (so
    // that the display continues scrolling)
    const startRender = () => {
      this.updatePitch();
      if (this.continuousUpdate) {
        requestAnimationFrame(startRender);
      }
    };
    startRender();
    window.addEventListener('resize', this.onResize);
    window.addEventListener('keydown', this.onKeyDown);
  }

  componentWillUnmount() {
    this.continuousUpdate = false;
    window.removeEventListener('resize', this.onResize);
    window.removeEventListener('keydown', this.onKeyDown);
  }

  onResize = () => {
    if (this.pitchDisplay) {
      this.pitchDisplay.resize();
    }
  }

  onKeyDown = (e: KeyboardEvent) => {
    if (e.repeat) return;
    if (e.code === 'KeyN') this.pitchDisplay?.toggleNoiseReduction();
  };

  updatePitch() {
    if (this.paused) {
      return;
    }
    const time = new Date().getTime();
    if (time - this.lastRender < 17) {
      // We don't want to render faster than 60fps
      return;
    }
    if (!this.pitchDisplay) {
      return;
    }
    const { freq, clarity } = this.props;
    if (freq && freq > 0) {
      this.pitchDisplay.pushFrequency({
        frequency: freq,
        clarity: clarity || 0,
        time,
      });
    }
    this.lastRender = time;
    this.pitchDisplay.setNow(time);
    this.pitchDisplay.render();
  }

  render() {
    this.updatePitch();
    if (this.pitchDisplay) {
      this.pitchDisplay.setNoteSpan(this.props.noteSpan ?? 0);
      this.pitchDisplay.setTimeSpan(this.props.timeSpan || 1);
    }
    return (
      <React.Fragment>
        <div
          className="full"
          style={{ position: 'relative' }}
          ref={this.displayElement}
          onMouseDown={() => this.paused = true}
          onTouchStart={() => this.paused = true}
          onMouseUp={() => this.paused = false}
          onTouchEnd={() => this.paused = false}
        />
      </React.Fragment>
    );
  }
}

export default PitchComponent;
